toolArgs.file_text:
.message-item {
    position: relative;
    padding: 0.5rem 0.75rem;
    border-radius: 6px;
    transition: background 0.1s;
}

.message-item:hover {
    background: #f5f6f8;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
    margin-bottom: 0.15rem;
}

.author {
    font-weight: 700;
    font-size: 0.92rem;
    color: #1a1a2e;
}

.timestamp {
    font-size: 0.75rem;
    color: #999;
}

.message-content {
    font-size: 0.92rem;
    line-height: 1.45;
    color: #333;
    word-break: break-word;
}

.reactions {
    display: flex;
    flex-wrap: wrap;
    gap: 0.3rem;
    margin-top: 0.35rem;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.2rem;
    padding: 0.15rem 0.45rem;
    background: #eef1f8;
    border: 1px solid #dde1ea;
    border-radius: 12px;
    font-size: 0.82rem;
    cursor: pointer;
    transition: background 0.12s;
}

.reaction-badge:hover {
    background: #dde3f0;
}

.reaction-count {
    font-size: 0.75rem;
    font-weight: 600;
    color: #555;
}

.thread-link {
    display: inline-block;
    margin-top: 0.3rem;
    background: none;
    border: none;
    color: #4a6cf7;
    font-size: 0.82rem;
    font-weight: 600;
    cursor: pointer;
    padding: 0;
}

.thread-link:hover {
    text-decoration: underline;
}

.action-bar {
    position: absolute;
    top: -0.5rem;
    right: 0.5rem;
    display: flex;
    gap: 0.15rem;
    background: #fff;
    border: 1px solid #dde1ea;
    border-radius: 6px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.1);
    padding: 0.15rem;
    z-index: 10;
}

.action-btn {
    background: none;
    border: none;
    padding: 0.25rem 0.5rem;
    font-size: 0.8rem;
    cursor: pointer;
    border-radius: 4px;
    white-space: nowrap;
    color: #555;
}

.action-btn:hover {
    background: #f0f2f5;
    color: #1a1a2e;
}

.emoji-picker {
    position: absolute;
    right: 0.5rem;
    top: 1.8rem;
    display: flex;
    gap: 0.15rem;
    background: #fff;
    border: 1px solid #dde1ea;
    border-radius: 8px;
    box-shadow: 0 4px 14px rgba(0,0,0,0.12);
    padding: 0.3rem;
    z-index: 20;
}

.emoji-btn {
    background: none;
    border: none;
    font-size: 1.3rem;
    cursor: pointer;
    padding: 0.25rem;
    border-radius: 4px;
    line-height: 1;
    transition: background 0.1s;
}

.emoji-btn:hover {
    background: #f0f2f5;
}

