arguments.file_text:
@using sv_c0e4cb4ecf8141c4a9a9db072a93cab9.Services

<div class="channel-sidebar">
    <div class="sidebar-header">
        <h3>Channels</h3>
    </div>
    <div class="channel-list">
        @foreach (var channel in Channels)
        {
            <ChannelItem Channel="channel"
                         IsActive="channel.Id == ActiveChannelId"
                         OnClick="() => OnChannelSelected.InvokeAsync(channel.Id)" />
        }
    </div>
</div>

@code {
    [Parameter] public List<Channel> Channels { get; set; } = [];
    [Parameter] public int? ActiveChannelId { get; set; }
    [Parameter] public EventCallback<int> OnChannelSelected { get; set; }
}

.channel-sidebar {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #2c2f3e;
    color: #fff;
}

.sidebar-header {
    padding: 1rem 0.75rem 0.5rem;
    border-bottom: 1px solid rgba(255,255,255,0.08);
}

.sidebar-header h3 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
    letter-spacing: 0.02em;
}

.channel-list {
    flex: 1;
    overflow-y: auto;
    padding: 0.4rem 0;
}

@using sv_c0e4cb4ecf8141c4a9a9db072a93cab9.Services
@inject IJSRuntime JS
@implements IAsyncDisposable

<div class="message-list" @ref="scrollContainer">
    @if (IsLoading)
    {
        <div class="loading-indicator">Loading messages…</div>
    }
    @foreach (var message in Messages)
    {
        var msg = message;
        var threadInfo = ThreadSummaries.FirstOrDefault(t => t.RootMessageId == msg.Id);
        <MessageItem Message="msg"
                     ShowThreadLink="@(threadInfo is not null)"
                     ReplyCount="@(threadInfo?.ReplyCount ?? 0)"
                     OnOpenThread="() => OnOpenThread.InvokeAsync(msg.Id)"
                     OnReact="emoji => OnReact.InvokeAsync((msg.Id, emoji))" />
    }
</div>

@code {
    [Parameter] public List<Message> Messages { get; set; } = [];
    [Parameter] public List<ThreadSummary> ThreadSummaries { get; set; } = [];
    [Parameter] public bool IsLoading { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private ElementReference scrollContainer;
    private IJSObjectReference? jsModule;
    private DotNetObjectReference<MessageList>? dotNetRef;
    private bool isFirstRender = true;
    private bool loadingMore;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
