+    {
+        if (loadingMore || IsLoading) return;
+        loadingMore = true;
+        var prevHeight = await GetScrollHeightAsync();
+        await OnLoadMore.InvokeAsync();
+        await Task.Yield();
+        StateHasChanged();
+        await Task.Delay(50);
+        await RestoreScrollAsync(prevHeight);
+        loadingMore = false;
+    }
+
+    public async ValueTask DisposeAsync()
+    {
+        if (jsModule is not null)
+        {
+            try
