arguments.file_text:
@using sv_c0e4cb4ecf8141c4a9a9db072a93cab9.Services

<div class="message-area">
    @if (CurrentChannel is not null)
    {
        <div class="area-header">
            <h2># @CurrentChannel.Name</h2>
            <p>@CurrentChannel.Description</p>
        </div>

        <MessageList @ref="messageListRef"
                     Messages="Messages"
                     ThreadSummaries="ThreadSummaries"
                     IsLoading="IsLoading"
                     OnLoadMore="OnLoadMore"
                     OnOpenThread="OnOpenThread"
                     OnReact="OnReact" />

        <MessageInput Placeholder="@($"Message #{CurrentChannel.Name}")"
                      ButtonText="Send"
                      OnSubmit="OnSendMessage" />
    }
    else
    {
        <div class="empty-state">
            <p>Select a channel to start chatting</p>
        </div>
    }
</div>

@code {
    [Parameter] public Channel? CurrentChannel { get; set; }
    [Parameter] public List<Message> Messages { get; set; } = [];
    [Parameter] public List<ThreadSummary> ThreadSummaries { get; set; } = [];
    [Parameter] public bool IsLoading { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }

    private MessageList? messageListRef;

    public async Task ScrollToBottomAsync()
    {
        if (messageListRef is not null)
            await messageListRef.ScrollToBottomAsync();
    }
}

.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #fff;
    border-left: 1px solid #e0e0e0;
    border-right: 1px solid #e0e0e0;
}

.area-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #e8e8e8;
    flex-shrink: 0;
}

.area-header h2 {
    margin: 0;
    font-size: 1.15rem;
    font-weight: 700;
    color: #1a1a2e;
}

.area-header p {
    margin: 0.15rem 0 0;
    font-size: 0.82rem;
    color: #888;
}

.empty-state {
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 1;
    color: #999;
    font-size: 1rem;
}

@using sv_c0e4cb4ecf8141c4a9a9db072a93cab9.Services

<div class="thread-panel">
    <div class="thread-header">
        <h3>Thread</h3>
        <button class="close-btn" @onclick="OnClose" title="Close thread">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root">
            <div class="root-author">@RootMessage.Author</div>
            <div class="root-content">@RootMessage.Content</div>
        </div>

        <div class="thread-divider">
            <span>@Replies.Count @(Replies.Count == 1 ? "reply" : "replies")</span>
        </div>

        <div class="thread-replies">
            @foreach (var reply in Replies)
            {
                <MessageItem Message="reply"
                             ShowThreadLink="false"
                             OnReact="emoji => OnReactInThread.InvokeAsync((reply.Id, emoji))" />
            }
        </div>

        <MessageInput Placeholder="Reply in thread…"
                      ButtonText="Reply"
                      OnSubmit="OnSendReply" />
    }
</div>

@code {
    [Parameter] public Message? RootMessage { get; set; }
    [Parameter] public List<Message> Replies { get; set; } = [];
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnSendReply { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReactInThread { get; set; }
}

.thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #fafbfc;
    border-left: 1px solid #e0e0e0;
}

.thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #e8e8e8;
    flex-shrink: 0;
}

.thread-header h3 {
    margin: 0;
    font-size: 1.05rem;
    font-weight: 700;
    color: #1a1a2e;
}

.close-btn {
    background: none;
    border: none;
    font-size: 1.1rem;
    cursor: pointer;
    color: #888;
    padding: 0.2rem 0.4rem;
    border-radius: 4px;
    line-height: 1;
    transition: background 0.12s;
}

.close-btn:hover {
    background: #eee;
    color: #333;
}

.thread-root {
    padding: 0.75rem 1rem;
    background: #f0f2f5;
    border-bottom: 1px solid #e8e8e8;
    flex-shrink: 0;
}

.root-author {
    font-weight: 700;
    font-size: 0.88rem;
    color: #1a1a2e;
    margin-bottom: 0.2rem;
}

.root-content {
    font-size: 0.88rem;
    color: #555;
    line-height: 1.4;
}

.thread-divider {
    padding: 0.4rem 1rem;
    font-size: 0.75rem;
    color: #999;
    border-bottom: 1px solid #e8e8e8;
    flex-shrink: 0;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 0.25rem 0;
}

