arguments.file_text:
@page "/chat"
@layout ChatLayout
@rendermode InteractiveServer
@using sv_c0e4cb4ecf8141c4a9a9db072a93cab9.Services
@using sv_c0e4cb4ecf8141c4a9a9db072a93cab9.Components.Chat
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-container">
    <div class="sidebar-panel">
        <ChannelSidebar Channels="channels"
                        ActiveChannelId="selectedChannelId"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="main-panel @(isThreadOpen ? "" : "expanded")">
        <MessageArea @ref="messageAreaRef"
                     CurrentChannel="CurrentChannel"
                     Messages="messages"
                     ThreadSummaries="threadSummaries"
                     IsLoading="isLoadingMessages"
                     OnLoadMore="LoadOlderMessages"
                     OnOpenThread="OpenThread"
                     OnReact="HandleReaction"
                     OnSendMessage="SendMessage" />
    </div>

    @if (isThreadOpen && threadRootMessage is not null)
    {
        <div class="thread-panel-container">
            <ThreadPanel RootMessage="threadRootMessage"
                         Replies="threadReplies"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply"
                         OnReactInThread="HandleReaction" />
        </div>
    }
</div>

@code {
    private const int PageSize = 30;

    private List<Channel> channels = [];
    private List<Message> messages = [];
    private List<ThreadSummary> threadSummaries = [];
    private int? selectedChannelId;
    private bool isLoadingMessages;

    // Thread state
    private bool isThreadOpen;
    private Message? threadRootMessage;
    private List<Message> threadReplies = [];

    private MessageArea? messageAreaRef;

    private Channel? CurrentChannel => channels.FirstOrDefault(c => c.Id == selectedChannelId);

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
    }

    private async Task SelectChannel(int channelId)
    {
        if (selectedChannelId == channelId) return;

        selectedChannelId = channelId;
        messages = [];
        threadSummaries = [];
        CloseThreadSync();

        isLoadingMessages = true;
        StateHasChanged();

        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        ComputeThreadSummaries();
        isLoadingMessages = false;

        await ChatService.MarkChannelReadAsync(channelId);
        UpdateChannelUnread(channelId);
        StateHasChanged();

        await Task.Yield();
        if (messageAreaRef is not null)
            await messageAreaRef.ScrollToBottomAsync();
    }

    private async Task LoadOlderMessages()
    {
        if (selectedChannelId is null || isLoadingMessages) return;

        isLoadingMessages = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(selectedChannelId.Value, messages.Count, PageSize);
        if (older.Count > 0)
        {
            messages.InsertRange(0, older);
            ComputeThreadSummaries();
        }

        isLoadingMessages = false;
        StateHasChanged();
    }

    private async Task SendMessage(string content)
    {
        if (selectedChannelId is null) return;

        var msg = await ChatService.SendMessageAsync(selectedChannelId.Value, content, null);
        messages.Add(msg);
        StateHasChanged();

        await Task.Yield();
        if (messageAreaRef is not null)
            await messageAreaRef.ScrollToBottomAsync();
    }

    private async Task OpenThread(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        if (threadRootMessage is null) return;

        threadReplies = await ChatService.GetThreadAsync(messageId);
        isThreadOpen = true;
        StateHasChanged();
    }

    private void CloseThread()
    {
        CloseThreadSync();
        StateHasChanged();
    }

    private void CloseThreadSync()
    {
        isThreadOpen = false;
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (selectedChannelId is null || threadRootMessage is null) return;

        var reply = await ChatService.SendMessageAsync(selectedChannelId.Value, content, threadRootMessage.Id);
        threadReplies.Add(reply);
        ComputeThreadSummaries();
        StateHasChanged();
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh the relevant message's reactions
        if (selectedChannelId is not null)
        {
            var updated = await ChatService.GetMessagesAsync(selectedChannelId.Value, 0, messages.Count);
            if (updated.Count > 0) messages = updated;

            if (isThreadOpen && threadRootMessage is not null)
            {
                threadReplies = await ChatService.GetThreadAsync(threadRootMessage.Id);
                threadRootMessage = messages.FirstOrDefault(m => m.Id == threadRootMessage.Id) ?? threadRootMessage;
            }

            StateHasChanged();
        }
    }

    private void ComputeThreadSummaries()
    {
        threadSummaries = messages
            .Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value)
            .Select(g => new ThreadSummary(
                g.Key,
                g.Count(),
                g.Max(m => m.SentAt)))
            .ToList();
    }

    private void UpdateChannelUnread(int channelId)
    {
        var idx = channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            var ch = channels[idx];
            channels[idx] = ch with { UnreadCount = 0 };
        }
    }
}

.chat-container {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

.sidebar-panel {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    flex-shrink: 0;
}

.main-panel {
    flex: 1;
    min-width: 0;
}

.main-panel.expanded {
    flex: 1;
}

.thread-panel-container {
    width: 25%;
    min-width: 260px;
    max-width: 400px;
    flex-shrink: 0;
}

